-- =============================================================================
-- 3. Quote lifecycle: staff may revise a sent quote or re-quote after expiry
-- =============================================================================
create or replace function public.app_quote_transition_allowed(p_from public.quote_status, p_to public.quote_status)
returns boolean language sql immutable set search_path = '' as $$
  select (p_from::text, p_to::text) in (
    ('SUBMITTED', 'UNDER_REVIEW'),
    ('UNDER_REVIEW', 'AWAITING_CUSTOMER'), ('UNDER_REVIEW', 'QUOTED'),
    ('AWAITING_CUSTOMER', 'UNDER_REVIEW'), ('AWAITING_CUSTOMER', 'QUOTED'),
    ('QUOTED', 'ACCEPTED'), ('QUOTED', 'DECLINED'), ('QUOTED', 'EXPIRED'),
    ('QUOTED', 'UNDER_REVIEW'), ('EXPIRED', 'UNDER_REVIEW')
  ) or (p_to::text = 'CANCELLED' and p_from::text <> 'CANCELLED')
$$;

-- =============================================================================
-- 4. Line-item pricing: totals are recomputed and verified when a quote is sent
-- =============================================================================
-- Amount of a non-tax line. round(numeric) rounds half away from zero; the
-- application uses the same rule with integer arithmetic (lib/domain/pricing.ts).
create or replace function public.app_quote_line_amount(p_kind public.quote_line_kind, p_quantity numeric, p_unit bigint)
returns bigint language sql immutable set search_path = '' as $$
  select case p_kind::text
    when 'charge' then round(p_quantity * p_unit)::bigint
    when 'discount' then -round(p_quantity * p_unit)::bigint
  end
$$;

-- Returns the verified total of a quote's lines, or NULL when it has none.
create or replace function public.app_quote_lines_total(p_quote_id uuid)
returns bigint language plpgsql stable security definer set search_path = '' as $$
declare
  v_lines integer;
  v_bad integer;
  v_base bigint;
begin
  select count(*) into v_lines from public.quote_line_items where quote_id = p_quote_id;
  if v_lines = 0 then
    return null;
  end if;
  select count(*) into v_bad from public.quote_line_items
   where quote_id = p_quote_id and kind <> 'tax'
     and line_total_minor <> public.app_quote_line_amount(kind, quantity, unit_amount_minor);
  if v_bad > 0 then
    raise exception 'quote_total_mismatch' using errcode = 'P0001';
  end if;
  select coalesce(sum(line_total_minor), 0) into v_base from public.quote_line_items where quote_id = p_quote_id and kind <> 'tax';
  if v_base <= 0 then
    raise exception 'quote_total_mismatch' using errcode = 'P0001', detail = 'subtotal must be positive';
  end if;
  -- Tax lines apply to the subtotal of charges and discounts.
  select count(*) into v_bad from public.quote_line_items
   where quote_id = p_quote_id and kind = 'tax' and line_total_minor <> round(v_base::numeric * rate_bp / 10000)::bigint;
  if v_bad > 0 then
    raise exception 'quote_total_mismatch' using errcode = 'P0001';
  end if;
  return (select sum(line_total_minor) from public.quote_line_items where quote_id = p_quote_id);
end
$$;

-- Quotes: created while the request is under review; frozen once sent; the
-- amount must equal the verified line total when lines exist.
create or replace function public.app_enforce_quote_rules() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_status public.quote_status;
  v_total bigint;
begin
  if tg_op = 'INSERT' then
    select r.status into v_status from public.quote_requests r where r.id = new.quote_request_id;
    if v_status is null or v_status not in ('UNDER_REVIEW', 'AWAITING_CUSTOMER') then
      raise exception 'quote_request_not_under_review' using errcode = 'P0001';
    end if;
    if auth.uid() is not null and new.created_by <> auth.uid() then
      raise exception 'created_by_mismatch' using errcode = 'P0001';
    end if;
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;

  if old.sent_at is not null then
    raise exception 'quote_already_sent' using errcode = 'P0001';
  end if;
  if new.quote_request_id <> old.quote_request_id or new.created_by <> old.created_by or new.created_at <> old.created_at then
    raise exception 'immutable_field' using errcode = 'P0001';
  end if;
  if new.sent_at is not null then
    v_total := public.app_quote_lines_total(new.id);
    if v_total is not null and v_total <> new.amount_minor then
      raise exception 'quote_total_mismatch' using errcode = 'P0001';
    end if;
  end if;
  return new;
end
$$;

-- Lines can be added or removed only while their quote is unsent; never edited.
create or replace function public.app_enforce_quote_line_rules() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_sent timestamptz;
begin
  select q.sent_at into v_sent from public.quotes q where q.id = coalesce(new.quote_id, old.quote_id);
  if v_sent is not null then
    raise exception 'quote_already_sent' using errcode = 'P0001';
  end if;
  if tg_op = 'UPDATE' then
    raise exception 'immutable_field' using errcode = 'P0001';
  end if;
  if tg_op = 'INSERT' then
    new.created_at := now();
    return new;
  end if;
  return old;
end
$$;
drop trigger if exists quote_line_items_rules on public.quote_line_items;
create trigger quote_line_items_rules before insert or update or delete on public.quote_line_items
  for each row execute function public.app_enforce_quote_line_rules();
drop trigger if exists quote_line_items_audit on public.quote_line_items;
create trigger quote_line_items_audit after insert or update or delete on public.quote_line_items
  for each row execute function public.app_audit_row();

-- =============================================================================
-- 5. Assignment and privacy acknowledgement on quote requests
-- =============================================================================
create or replace function public.app_enforce_quote_request_extras() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.assigned_to is distinct from old.assigned_to and new.assigned_to is not null
     and not exists (select 1 from public.profiles p where p.id = new.assigned_to and p.role in ('staff', 'admin')) then
    raise exception 'assignee_not_staff' using errcode = 'P0001';
  end if;
  if new.privacy_accepted_at is distinct from old.privacy_accepted_at then
    raise exception 'immutable_field' using errcode = 'P0001';
  end if;
  return new;
end
$$;
drop trigger if exists quote_requests_extras on public.quote_requests;
create trigger quote_requests_extras before update on public.quote_requests
  for each row execute function public.app_enforce_quote_request_extras();

-- =============================================================================
-- 6. Case messages: append-only, author derived from the session
-- =============================================================================
create or replace function public.app_enforce_case_message_rules() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op <> 'INSERT' then
    raise exception 'immutable_field' using errcode = 'P0001';
  end if;
  if auth.uid() is not null then
    if new.author_id is distinct from auth.uid() then
      raise exception 'created_by_mismatch' using errcode = 'P0001';
    end if;
    if new.author_kind = 'staff' and not public.app_is_staff() then
      raise exception 'forbidden' using errcode = 'P0001';
    end if;
  end if;
  if new.shipment_id is not null and not exists (
    select 1 from public.shipments s join public.quotes q on q.id = s.quote_id
     where s.id = new.shipment_id and q.quote_request_id = new.quote_request_id) then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  new.created_at := now();
  return new;
end
$$;
drop trigger if exists case_messages_rules on public.case_messages;
create trigger case_messages_rules before insert or update or delete on public.case_messages
  for each row execute function public.app_enforce_case_message_rules();
drop trigger if exists case_messages_audit on public.case_messages;
create trigger case_messages_audit after insert on public.case_messages
  for each row execute function public.app_audit_row('body');

-- =============================================================================
-- 7. Shipment status transitions (a delivered shipment never moves back)
-- =============================================================================
create or replace function public.app_shipment_transition_allowed(p_from public.shipment_status, p_to public.shipment_status)
returns boolean language sql immutable set search_path = '' as $$
  select (p_from::text, p_to::text) in (
    ('BOOKED', 'IN_TRANSIT'), ('BOOKED', 'ON_HOLD'), ('BOOKED', 'CANCELLED'),
    ('IN_TRANSIT', 'AT_DESTINATION'), ('IN_TRANSIT', 'DELIVERED'), ('IN_TRANSIT', 'ON_HOLD'),
    ('AT_DESTINATION', 'DELIVERED'), ('AT_DESTINATION', 'ON_HOLD'),
    ('ON_HOLD', 'BOOKED'), ('ON_HOLD', 'IN_TRANSIT'), ('ON_HOLD', 'AT_DESTINATION'), ('ON_HOLD', 'CANCELLED')
  )
$$;
create or replace function public.app_enforce_shipment_transition() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.status <> old.status and not public.app_shipment_transition_allowed(old.status, new.status) then
    raise exception 'invalid_shipment_transition' using errcode = 'P0001', detail = old.status || ' -> ' || new.status;
  end if;
  return new;
end
$$;
drop trigger if exists shipments_transition on public.shipments;
create trigger shipments_transition before update of status on public.shipments
  for each row execute function public.app_enforce_shipment_transition();

-- =============================================================================
-- 8. Contact enquiries and job runs
-- =============================================================================
drop trigger if exists contact_enquiries_touch on public.contact_enquiries;
create trigger contact_enquiries_touch before update on public.contact_enquiries
  for each row execute function public.app_touch_updated_at();
drop trigger if exists contact_enquiries_audit on public.contact_enquiries;
create trigger contact_enquiries_audit after insert or update or delete on public.contact_enquiries
  for each row execute function public.app_audit_row('name', 'email', 'phone', 'message');

-- =============================================================================
-- 9. Email outbox. Business events enqueue emails in the SAME transaction as
-- the change (database triggers), so a committed change can never lose its
-- notification and a rolled-back change never sends one. The server delivers
-- PENDING rows afterwards, with retries and provider webhooks.
-- =============================================================================
create or replace function public.app_enqueue_email(
  p_template text, p_audience text, p_entity text, p_entity_id text, p_key text,
  p_recipient text, p_locale public.app_locale, p_payload jsonb default '{}'::jsonb
) returns void language sql security definer set search_path = '' as $$
  insert into public.email_deliveries (template, audience, entity, entity_id, idempotency_key, recipient, locale, payload, status, next_attempt_at)
  values (p_template, p_audience, p_entity, p_entity_id, p_key,
          case when p_audience = 'staff' then null else p_recipient end,
          p_locale, coalesce(p_payload, '{}'::jsonb), 'PENDING', now())
  on conflict (idempotency_key) do nothing
$$;

create or replace function public.app_notify_quote_request() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_email text;
  v_quote uuid;
  v_sent integer;
  v_stamp text := (extract(epoch from clock_timestamp()) * 1000)::bigint::text;
begin
  select c.email into v_email from public.customers c where c.id = new.customer_id;
  if tg_op = 'INSERT' then
    perform public.app_enqueue_email('quote_received', 'customer', 'quote_requests', new.id::text, 'quote_received:' || new.id, v_email, new.locale);
    perform public.app_enqueue_email('staff_new_request', 'staff', 'quote_requests', new.id::text, 'staff_new_request:' || new.id, null, 'en');
    return null;
  end if;
  if new.status = old.status then
    return null;
  end if;
  case new.status::text
    when 'UNDER_REVIEW' then
      if old.status = 'SUBMITTED' then
        perform public.app_enqueue_email('quote_under_review', 'customer', 'quote_requests', new.id::text, 'quote_under_review:' || new.id, v_email, new.locale);
      end if;
    when 'AWAITING_CUSTOMER' then
      perform public.app_enqueue_email('info_requested', 'customer', 'quote_requests', new.id::text, 'info_requested:' || new.id || ':' || v_stamp, v_email, new.locale);
    when 'QUOTED' then
      select q.id into v_quote from public.quotes q
       where q.quote_request_id = new.id and q.sent_at is not null order by q.sent_at desc limit 1;
      select count(*) into v_sent from public.quotes q where q.quote_request_id = new.id and q.sent_at is not null;
      perform public.app_enqueue_email(case when v_sent > 1 then 'quote_updated' else 'quote_issued' end, 'customer', 'quotes',
        v_quote::text, 'quote_issued:' || v_quote, v_email, new.locale, jsonb_build_object('quoteRequestId', new.id));
    when 'ACCEPTED' then
      perform public.app_enqueue_email('quote_accepted', 'customer', 'quote_requests', new.id::text, 'quote_accepted:' || new.id, v_email, new.locale);
      perform public.app_enqueue_email('staff_quote_accepted', 'staff', 'quote_requests', new.id::text, 'staff_quote_accepted:' || new.id, null, 'en');
    when 'DECLINED' then
      perform public.app_enqueue_email('quote_declined', 'customer', 'quote_requests', new.id::text, 'quote_declined:' || new.id, v_email, new.locale);
      perform public.app_enqueue_email('staff_quote_declined', 'staff', 'quote_requests', new.id::text, 'staff_quote_declined:' || new.id, null, 'en');
    when 'EXPIRED' then
      perform public.app_enqueue_email('quote_expired', 'customer', 'quote_requests', new.id::text, 'quote_expired:' || new.id || ':' || v_stamp, v_email, new.locale);
    else
      null;
  end case;
  return null;
end
$$;
drop trigger if exists quote_requests_notify on public.quote_requests;
create trigger quote_requests_notify after insert or update of status on public.quote_requests
  for each row execute function public.app_notify_quote_request();

create or replace function public.app_notify_case_message() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.author_kind = 'customer' then
    perform public.app_enqueue_email('staff_customer_message', 'staff', 'case_messages', new.id::text,
      'staff_customer_message:' || new.id, null, 'en', jsonb_build_object('kind', new.kind));
  end if;
  return null;
end
$$;
drop trigger if exists case_messages_notify on public.case_messages;
create trigger case_messages_notify after insert on public.case_messages
  for each row execute function public.app_notify_case_message();

create or replace function public.app_notify_shipment() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_email text;
  v_locale public.app_locale;
begin
  select c.email, r.locale into v_email, v_locale
    from public.customers c, public.quotes q join public.quote_requests r on r.id = q.quote_request_id
   where c.id = new.customer_id and q.id = new.quote_id;
  if tg_op = 'INSERT' then
    perform public.app_enqueue_email('shipment_confirmed', 'customer', 'shipments', new.id::text, 'shipment_confirmed:' || new.id, v_email, v_locale);
  elsif new.status <> old.status and new.status = 'ON_HOLD' then
    perform public.app_enqueue_email('staff_shipment_exception', 'staff', 'shipments', new.id::text,
      'staff_shipment_on_hold:' || new.id || ':' || (extract(epoch from clock_timestamp()) * 1000)::bigint, null, 'en',
      jsonb_build_object('reason', 'ON_HOLD'));
  end if;
  return null;
end
$$;
drop trigger if exists shipments_notify on public.shipments;
create trigger shipments_notify after insert or update of status on public.shipments
  for each row execute function public.app_notify_shipment();

create or replace function public.app_notify_shipment_event() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_email text;
  v_locale public.app_locale;
begin
  if (tg_op = 'INSERT' and new.public) or (tg_op = 'UPDATE' and new.public and not old.public) then
    select c.email, r.locale into v_email, v_locale
      from public.shipments s
      join public.customers c on c.id = s.customer_id
      join public.quotes q on q.id = s.quote_id
      join public.quote_requests r on r.id = q.quote_request_id
     where s.id = new.shipment_id;
    perform public.app_enqueue_email(case when new.milestone_code = 'DELIVERED' then 'shipment_delivered' else 'shipment_update' end,
      'customer', 'shipment_events', new.id::text, 'shipment_event:' || new.id, v_email, v_locale);
  end if;
  if tg_op = 'INSERT' and new.milestone_code = 'DELAYED' then
    perform public.app_enqueue_email('staff_shipment_exception', 'staff', 'shipment_events', new.id::text,
      'staff_shipment_delayed:' || new.id, null, 'en', jsonb_build_object('reason', 'DELAYED'));
  end if;
  return null;
end
$$;
drop trigger if exists shipment_events_notify on public.shipment_events;
create trigger shipment_events_notify after insert or update of public on public.shipment_events
  for each row execute function public.app_notify_shipment_event();

create or replace function public.app_notify_contact() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  perform public.app_enqueue_email('contact_received', 'customer', 'contact_enquiries', new.id::text, 'contact_received:' || new.id, new.email, new.locale);
  perform public.app_enqueue_email('staff_contact', 'staff', 'contact_enquiries', new.id::text, 'staff_contact:' || new.id, null, 'en');
  return null;
end
$$;
drop trigger if exists contact_enquiries_notify on public.contact_enquiries;
create trigger contact_enquiries_notify after insert on public.contact_enquiries
  for each row execute function public.app_notify_contact();

create or replace function public.app_notify_role_change() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.role <> old.role then
    perform public.app_enqueue_email('staff_role_changed', 'staff', 'profiles', new.id::text,
      'staff_role_changed:' || new.id || ':' || (extract(epoch from clock_timestamp()) * 1000)::bigint, null, 'en',
      jsonb_build_object('from', old.role, 'to', new.role, 'by', auth.uid()));
  end if;
  return null;
end
$$;
drop trigger if exists profiles_notify on public.profiles;
create trigger profiles_notify after update of role on public.profiles
  for each row execute function public.app_notify_role_change();

-- =============================================================================
-- 10. Secure quote links (customers without an account). The server verifies
-- the signed link before calling this; never granted to client roles.
-- =============================================================================
create or replace function public.app_link_respond_to_quote(p_quote_request_id uuid, p_accept boolean) returns public.quote_status
language plpgsql security definer set search_path = '' as $$
declare
  v_status public.quote_status;
begin
  select r.status into v_status from public.quote_requests r where r.id = p_quote_request_id for update;
  if v_status is null then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  if v_status <> 'QUOTED' then
    raise exception 'invalid_quote_transition' using errcode = 'P0001';
  end if;
  update public.quote_requests
     set status = case when p_accept then 'ACCEPTED'::public.quote_status else 'DECLINED'::public.quote_status end
   where id = p_quote_request_id;
  return case when p_accept then 'ACCEPTED'::public.quote_status else 'DECLINED'::public.quote_status end;
end
$$;

-- =============================================================================
-- 11. Public tracking: adds the route and the delivery time to the allowlist
-- =============================================================================
create or replace function public.public_track_shipment(p_reference text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'reference', s.reference,
    'serviceCode', s.service_code,
    'status', s.status,
    'origin', r.origin_country,
    'destination', r.destination_country,
    'etaFrom', case when s.eta_visible then s.eta_from end,
    'etaTo', case when s.eta_visible then s.eta_to end,
    'deliveredAt', (select max(e.occurred_at) from public.shipment_events e
                     where e.shipment_id = s.id and e.public and e.milestone_code = 'DELIVERED'),
    'events', coalesce((
      select jsonb_agg(jsonb_build_object(
               'milestone', e.milestone_code,
               'location', e.location,
               'occurredAt', e.occurred_at,
               'noteEn', e.note_en,
               'noteFr', e.note_fr) order by e.occurred_at desc)
        from public.shipment_events e
       where e.shipment_id = s.id and e.public), '[]'::jsonb)
  )
  from public.shipments s
  join public.quotes q on q.id = s.quote_id
  join public.quote_requests r on r.id = q.quote_request_id
  where s.reference = upper(btrim(p_reference))
    and upper(btrim(p_reference)) ~ '^ML[A-Z2-7]{10}$'
$$;

-- =============================================================================
-- 12. Row Level Security and grants
-- =============================================================================
alter table public.quote_line_items enable row level security;
alter table public.case_messages enable row level security;
alter table public.contact_enquiries enable row level security;
alter table public.job_runs enable row level security;

drop policy if exists quote_line_items_select on public.quote_line_items;
create policy quote_line_items_select on public.quote_line_items for select to authenticated
  using (public.app_is_staff() or exists (
    select 1 from public.quotes q join public.quote_requests r on r.id = q.quote_request_id
     where q.id = quote_id and q.sent_at is not null and public.app_owns_customer(r.customer_id)));
drop policy if exists quote_line_items_staff_insert on public.quote_line_items;
create policy quote_line_items_staff_insert on public.quote_line_items for insert to authenticated with check (public.app_is_staff());
drop policy if exists quote_line_items_staff_delete on public.quote_line_items;
create policy quote_line_items_staff_delete on public.quote_line_items for delete to authenticated using (public.app_is_staff());

drop policy if exists case_messages_select on public.case_messages;
create policy case_messages_select on public.case_messages for select to authenticated
  using (public.app_is_staff() or (not internal and exists (
    select 1 from public.quote_requests r where r.id = quote_request_id and public.app_owns_customer(r.customer_id))));
drop policy if exists case_messages_staff_insert on public.case_messages;
create policy case_messages_staff_insert on public.case_messages for insert to authenticated
  with check (public.app_is_staff() and author_kind = 'staff');
drop policy if exists case_messages_customer_insert on public.case_messages;
create policy case_messages_customer_insert on public.case_messages for insert to authenticated
  with check (author_kind = 'customer' and not internal and exists (
    select 1 from public.quote_requests r where r.id = quote_request_id and public.app_owns_customer(r.customer_id)));

drop policy if exists contact_enquiries_staff_select on public.contact_enquiries;
create policy contact_enquiries_staff_select on public.contact_enquiries for select to authenticated using (public.app_is_staff());
drop policy if exists contact_enquiries_staff_update on public.contact_enquiries;
create policy contact_enquiries_staff_update on public.contact_enquiries for update to authenticated
  using (public.app_is_staff()) with check (public.app_is_staff());

drop policy if exists job_runs_staff_select on public.job_runs;
create policy job_runs_staff_select on public.job_runs for select to authenticated using (public.app_is_staff());

grant select (assigned_to, privacy_accepted_at) on public.quote_requests to authenticated;
grant update (assigned_to) on public.quote_requests to authenticated;
grant select, insert, delete on public.quote_line_items to authenticated;
-- author_id is not readable by client roles (staff identities stay internal).
grant select (id, quote_request_id, shipment_id, author_kind, internal, kind, body, created_at) on public.case_messages to authenticated;
grant insert (id, quote_request_id, shipment_id, author_kind, author_id, internal, kind, body, created_at) on public.case_messages to authenticated;
grant select on public.contact_enquiries to authenticated;
grant update (status) on public.contact_enquiries to authenticated;
grant select on public.job_runs to authenticated;
grant execute on function public.app_shipment_transition_allowed(public.shipment_status, public.shipment_status) to authenticated;
grant execute on function public.app_quote_line_amount(public.quote_line_kind, numeric, bigint) to authenticated;
